def forward(self, taskInfo):
    """Solve an ARC task by aggregating deterministic hypotheses, code candidates, and a direct answer.
    The final output grid is the one with the highest vote; ties are broken by source priority:
    deterministic > code > direct.
    """

    # ---------------------------------------------------------------------
    # 0. Guard – if no examples are provided, fall back to a direct answer.
    # ---------------------------------------------------------------------
    if not self.examples:
        fallback_instruction = (
            "Please examine the three example input‑output pairs, infer the transformation rule, "
            "and then apply that rule to the test input given at the end. Return ONLY the resulting "
            "grid as a JSON list of lists of integers."
        )
        direct_agent = LLMAgentBase(
            output_fields=["answer"],
            agent_name="DirectAnswerFallback",
            role="ARC Solver",
            temperature=0.1,
        )
        answer_info = direct_agent([taskInfo], fallback_instruction)[0]
        return answer_info.content

    # ---------------------------------------------------------------------
    # Helper deterministic transformations
    # ---------------------------------------------------------------------
    def crop_vertical(grid, sep_c, keep_left):
        return [row[:sep_c] if keep_left else row[sep_c + 1 :] for row in grid]

    def crop_horizontal(grid, sep_r, keep_top):
        return grid[:sep_r] if keep_top else grid[sep_r + 1 :]

    def remove_colour(grid, colour):
        return [[0 if cell == colour else cell for cell in row] for row in grid]

    def replace_colour(grid, src, dst):
        return [[dst if cell == src else cell for cell in row] for row in grid]

    def extract_bbox(grid, colour):
        rows = [i for i, row in enumerate(grid) if colour in row]
        cols = [j for j in range(len(grid[0])) if any(grid[i][j] == colour for i in range(len(grid)))]
        if not rows or not cols:
            return None
        r0, r1 = min(rows), max(rows) + 1
        c0, c1 = min(cols), max(cols) + 1
        return [grid[i][c0:c1] for i in range(r0, r1)]

    # ---------------------------------------------------------------------
    # Families that generate (apply_fn, description) tuples for deterministic search
    # ---------------------------------------------------------------------
    def vertical_crop_candidates():
        common = None
        for ex in self.examples:
            grid = ex['input']
            n_rows, n_cols = len(grid), len(grid[0])
            cols = []
            for c in range(n_cols):
                col_vals = [grid[r][c] for r in range(n_rows)]
                if all(v == col_vals[0] for v in col_vals):
                    cols.append((c, col_vals[0]))
            common = set(cols) if common is None else common & set(cols)
        if not common:
            return []
        cand = []
        for sep_c, colour in common:
            def left_fn(g, sc=sep_c):
                return crop_vertical(g, sc, True)
            def right_fn(g, sc=sep_c):
                return crop_vertical(g, sc, False)
            cand.append((left_fn, f"vertical left of col {sep_c} (sep colour {colour})"))
            cand.append((right_fn, f"vertical right of col {sep_c} (sep colour {colour})"))
        return cand

    def horizontal_crop_candidates():
        common = None
        for ex in self.examples:
            grid = ex['input']
            n_rows, n_cols = len(grid), len(grid[0])
            rows = []
            for r in range(n_rows):
                row_vals = grid[r]
                if all(v == row_vals[0] for v in row_vals):
                    rows.append((r, row_vals[0]))
            common = set(rows) if common is None else common & set(rows)
        if not common:
            return []
        cand = []
        for sep_r, colour in common:
            def top_fn(g, sr=sep_r):
                return crop_horizontal(g, sr, True)
            def bottom_fn(g, sr=sep_r):
                return crop_horizontal(g, sr, False)
            cand.append((top_fn, f"horizontal top of row {sep_r} (sep colour {colour})"))
            cand.append((bottom_fn, f"horizontal bottom of row {sep_r} (sep colour {colour})"))
        return cand

    def colour_removal_candidates():
        colours = set()
        for ex in self.examples:
            for row in ex['input']:
                colours.update([c for c in row if c != 0])
        colours.add(0)  # also allow removing background
        cand = []
        for col in colours:
            def fn(g, colour=col):
                return remove_colour(g, colour)
            cand.append((fn, f"remove colour {col}"))
        return cand

    def colour_replace_candidates():
        colours = set()
        for ex in self.examples:
            for row in ex['input']:
                colours.update([c for c in row if c != 0])
        colours.add(0)
        cand = []
        for src in colours:
            for dst in colours:
                if src != dst:
                    def fn(g, s=src, d=dst):
                        return replace_colour(g, s, d)
                    cand.append((fn, f"replace {src} with {dst}"))
        return cand

    def bbox_candidates():
        colours = set()
        for ex in self.examples:
            for row in ex['input']:
                colours.update([c for c in row if c != 0])
        cand = []
        for col in colours:
            def fn(g, colour=col):
                return extract_bbox(g, colour)
            cand.append((fn, f"extract bbox of colour {col}"))
        return cand

    hypothesis_families = [
        vertical_crop_candidates,
        horizontal_crop_candidates,
        colour_removal_candidates,
        colour_replace_candidates,
        bbox_candidates,
    ]

    # ---------------------------------------------------------------------
    # 1. Deterministic hypothesis search – collect every hypothesis that matches all examples.
    # ---------------------------------------------------------------------
    deterministic_outputs = []
    for family_fn in hypothesis_families:
        for apply_fn, _ in family_fn():  # description is intentionally ignored
            all_match = True
            for ex in self.examples:
                inp = ex['input']
                out_expected = ex['output']
                out_candidate = apply_fn(inp)
                if out_candidate is None or out_candidate != out_expected:
                    all_match = False
                    break
            if all_match:
                test_out = apply_fn(self.test_input)
                if isinstance(test_out, list) and all(isinstance(r, list) for r in test_out):
                    deterministic_outputs.append(test_out)

    # ---------------------------------------------------------------------
    # 2. Rule‑guided code generation – keep candidates that solve all examples or a strict majority (2/3).
    # ---------------------------------------------------------------------
    rule_instruction = (
        "Examine the three example input‑output pairs and describe in a single sentence "
        "the transformation rule that maps any input grid to its output grid. "
        "Do not mention specific colours or coordinates; just state the general rule. "
        "Return only the description as plain text."
    )
    rule_agent = LLMAgentBase(
        output_fields=["thinking"],
        agent_name="RuleExtractor",
        role="Rule Extractor",
        temperature=0.1,
    )
    rule_info = rule_agent([taskInfo], rule_instruction)[0]
    rule_text = rule_info.content

    code_outputs = []
    N_code = 5
    for i in range(N_code):
        code_prompt = (
            f"Rule: {rule_text}\n"
            "Based on the rule, write a Python function named `transform` that takes a "
            "list[list[int]] as input and returns the transformed grid. The function must "
            "work for the three example input‑output pairs provided in the task description."
        )
        code_agent = LLMAgentBase(
            output_fields=["thinking", "code"],
            agent_name=f"CodeGen_{i}",
            role="Code Generator",
            temperature=0.7,
        )
        _ , code_info = code_agent([taskInfo], code_prompt, iteration_idx=i)
        _ , correct_examples, _ = self.run_examples_and_get_feedback(code_info)
        correct_cnt = len(correct_examples)
        if correct_cnt == len(self.examples) or correct_cnt >= 2:
            out_grid = self.get_test_output_from_code(code_info)
            if isinstance(out_grid, list) and all(isinstance(r, list) for r in out_grid):
                code_outputs.append(out_grid)

    # ---------------------------------------------------------------------
    # 3. Direct answer (low temperature) – only add if well‑formed.
    # ---------------------------------------------------------------------
    fallback_instruction = (
        "Please examine the three example input‑output pairs, infer the transformation rule, "
        "and then apply that rule to the test input given at the end. Return ONLY the resulting "
        "grid as a JSON list of lists of integers."
    )
    direct_agent = LLMAgentBase(
        output_fields=["answer"],
        agent_name="DirectAnswerFallback",
        role="ARC Solver",
        temperature=0.1,
    )
    answer_info = direct_agent([taskInfo], fallback_instruction)[0]
    direct_output = answer_info.content if isinstance(answer_info.content, list) and all(isinstance(r, list) for r in answer_info.content) else None

    # ---------------------------------------------------------------------
    # 4. Voting over all gathered outputs
    # ---------------------------------------------------------------------
    all_outputs = []
    source_tags = []  # parallel list indicating the origin of each grid
    for g in deterministic_outputs:
        all_outputs.append(g)
        source_tags.append('deterministic')
    for g in code_outputs:
        all_outputs.append(g)
        source_tags.append('code')
    if direct_output is not None:
        all_outputs.append(direct_output)
        source_tags.append('direct')

    if not all_outputs:
        # No valid outputs – return whatever the direct agent gave (even if malformed)
        return answer_info.content

    # Vote counting – use a hashable representation for each grid
    order = {'deterministic': 3, 'code': 2, 'direct': 1}
    vote_counts = {}
    best_source_for_key = {}
    for grid, src in zip(all_outputs, source_tags):
        key = tuple(tuple(row) for row in grid)
        vote_counts[key] = vote_counts.get(key, 0) + 1
        # Keep the highest‑priority source seen for this grid
        prev_src = best_source_for_key.get(key)
        if prev_src is None or order[src] > order.get(prev_src, 0):
            best_source_for_key[key] = src

    # Choose the grid with the highest vote count; break ties by source priority
    best_key, best_votes = max(vote_counts.items(), key=lambda kv: (kv[1], order[best_source_for_key[kv[0]]]))
    best_grid = [list(row) for row in best_key]
    return best_grid

def forward(self, taskInfo):
    """Solve an ARC task using a hierarchy of deterministic detectors followed by
    code generation/repair and a final direct‑answer fallback.

    Deterministic detectors (in order):
    1️⃣ Global colour‑mapping inference (permissive, includes colour 0, many‑to‑one).
    2️⃣ Uniform separator‑crop detector (keeps whole side of a uniform separator).
    3️⃣ Bounding‑box around cells that differ from the separator colour.
    4️⃣ Simple families (vertical/horizontal crops, colour removal/replacement, bbox).
    If none succeed, fall back to rule‑guided code generation/repair and finally a
    low‑temperature direct answer model.
    Returns the output grid as a list of list of ints.
    """

    # ---------------------------------------------------------------------
    # Helper utilities
    # ---------------------------------------------------------------------
    def is_grid(g):
        """Return True if *g* is a list of list of ints (or any objects)."""
        return isinstance(g, list) and all(isinstance(r, list) for r in g)

    # ---------------------------------------------------------------------
    # Guard – no examples → direct answer
    # ---------------------------------------------------------------------
    if not self.examples:
        fallback_instr = (
            "Please examine the three example input‑output pairs, infer the transformation rule, "
            "and then apply that rule to the test input given at the end. Return ONLY the resulting "
            "grid as a JSON list of lists of integers."
        )
        direct_agent = LLMAgentBase(
            output_fields=["answer"],
            agent_name="DirectAnswerFallback",
            role="ARC Solver",
            temperature=0.1,
        )
        return direct_agent([taskInfo], fallback_instr)[0].content

    # ---------------------------------------------------------------------
    # 1️⃣ Colour‑mapping detector (permissive, many‑to‑one allowed)
    # ---------------------------------------------------------------------
    def infer_color_mapping(examples):
        """Return a dict mapping each input colour (including 0) to an output colour
        if a *consistent* translation exists across all examples. Many‑to‑one mappings
        are allowed (different inputs may map to the same output)."""
        mapping = {}
        for ex in examples:
            inp, out = ex['input'], ex['output']
            if len(inp) != len(out) or len(inp[0]) != len(out[0]):
                return None  # size mismatch → cannot be pure colour mapping
            for r in range(len(inp)):
                for c in range(len(inp[0])):
                    ic, oc = inp[r][c], out[r][c]
                    if ic in mapping:
                        if mapping[ic] != oc:
                            return None
                    else:
                        mapping[ic] = oc
        return mapping

    colour_map = infer_color_mapping(self.examples)
    if colour_map is not None:
        def apply_colour_map(grid):
            return [[colour_map.get(cell, cell) for cell in row] for row in grid]
        if all(apply_colour_map(ex['input']) == ex['output'] for ex in self.examples):
            test_out = apply_colour_map(self.test_input)
            if is_grid(test_out):
                return test_out
        # If something unexpected happens, proceed to the next stage.

    # ---------------------------------------------------------------------
    # Helper: detect a uniform separator line (vertical or horizontal) present in every example
    # Returns (orientation, index, colour) or None.
    # ---------------------------------------------------------------------
    def detect_uniform_separator(examples):
        # ----- vertical -----
        common_cols = None
        for ex in examples:
            grid = ex["input"]
            n_rows, n_cols = len(grid), len(grid[0])
            cols = []
            for c in range(n_cols):
                col_vals = [grid[r][c] for r in range(n_rows)]
                if all(v == col_vals[0] for v in col_vals):
                    cols.append((c, col_vals[0]))
            common_cols = set(cols) if common_cols is None else common_cols & set(cols)
        if common_cols:
            col_idx, colour = next(iter(common_cols))
            return ("vertical", col_idx, colour)
        # ----- horizontal -----
        common_rows = None
        for ex in examples:
            grid = ex["input"]
            n_rows, n_cols = len(grid), len(grid[0])
            rows = []
            for r in range(n_rows):
                row_vals = grid[r]
                if all(v == row_vals[0] for v in row_vals):
                    rows.append((r, row_vals[0]))
            common_rows = set(rows) if common_rows is None else common_rows & set(rows)
        if common_rows:
            row_idx, colour = next(iter(common_rows))
            return ("horizontal", row_idx, colour)
        return None

    # Compute separator information once and reuse it
    sep_info = detect_uniform_separator(self.examples)

    # ---------------------------------------------------------------------
    # 2️⃣ Simple separator‑crop detector (keeps whole side of separator)
    # ---------------------------------------------------------------------
    def separator_crop(examples, sep_info):
        if sep_info is None:
            return None
        orientation, idx, _ = sep_info
        for side in ("left", "right") if orientation == "vertical" else ("top", "bottom"):
            ok = True
            for ex in examples:
                inp, out = ex["input"], ex["output"]
                if orientation == "vertical":
                    cand = [row[:idx] if side == "left" else row[idx + 1 :] for row in inp]
                else:
                    cand = inp[:idx] if side == "top" else inp[idx + 1 :]
                if cand != out:
                    ok = False
                    break
            if ok:
                test = self.test_input
                if orientation == "vertical":
                    return [row[:idx] if side == "left" else row[idx + 1 :] for row in test]
                else:
                    return test[:idx] if side == "top" else test[idx + 1 :]
        return None

    sep_result = separator_crop(self.examples, sep_info)
    if sep_result is not None and is_grid(sep_result):
        return sep_result

    # ---------------------------------------------------------------------
    # 3️⃣ Bounding‑box detector around cells that differ from the separator colour
    # ---------------------------------------------------------------------
    def bounding_box_via_separator(examples, sep_info):
        if sep_info is None:
            return None
        orientation, sep_idx, sep_colour = sep_info
        boxes = []
        side_consistency = None
        for ex in examples:
            inp = ex["input"]
            rows, cols = len(inp), len(inp[0])
            coords = [(r, c) for r in range(rows) for c in range(cols) if inp[r][c] != sep_colour]
            if not coords:
                return None
            rs, cs = zip(*coords)
            r0, r1 = min(rs), max(rs) + 1
            c0, c1 = min(cs), max(cs) + 1
            h, w = r1 - r0, c1 - c0
            boxes.append((r0, c0, h, w))
            # side detection
            if orientation == "vertical":
                cur_side = "left" if c0 + w == sep_idx else "right" if c0 == sep_idx + 1 else None
            else:
                cur_side = "top" if r0 + h == sep_idx else "bottom" if r0 == sep_idx + 1 else None
            if cur_side is None:
                return None
            if side_consistency is None:
                side_consistency = cur_side
            elif side_consistency != cur_side:
                return None
        # uniform size check
        first_h, first_w = boxes[0][2], boxes[0][3]
        if not all(b[2] == first_h and b[3] == first_w for b in boxes):
            return None
        # apply to test input
        r0, c0 = boxes[0][0], boxes[0][1]
        test = self.test_input
        result = [test[r0 + i][c0:c0 + first_w] for i in range(first_h)]
        return result if is_grid(result) else None

    bbox_result = bounding_box_via_separator(self.examples, sep_info)
    if bbox_result is not None:
        return bbox_result

    # ---------------------------------------------------------------------
    # 4️⃣ Remaining simple deterministic families (crop, colour removal/replacement, bbox)
    # ---------------------------------------------------------------------
    def crop_vertical(grid, sep_c, keep_left):
        return [row[:sep_c] if keep_left else row[sep_c + 1 :] for row in grid]

    def crop_horizontal(grid, sep_r, keep_top):
        return grid[:sep_r] if keep_top else grid[sep_r + 1 :]

    def remove_colour(grid, colour):
        return [[0 if cell == colour else cell for cell in row] for row in grid]

    def replace_colour(grid, src, dst):
        return [[dst if cell == src else cell for cell in row] for row in grid]

    def extract_bbox(grid, colour):
        rows = [i for i, row in enumerate(grid) if colour in row]
        cols = [j for j in range(len(grid[0])) if any(grid[i][j] == colour for i in range(len(grid)))]
        if not rows or not cols:
            return None
        r0, r1 = min(rows), max(rows) + 1
        c0, c1 = min(cols), max(cols) + 1
        return [grid[i][c0:c1] for i in range(r0, r1)]

    # Families generating (apply_fn, description) tuples
    def vertical_crop_candidates():
        common = None
        for ex in self.examples:
            grid = ex['input']
            n_rows, n_cols = len(grid), len(grid[0])
            cols = []
            for c in range(n_cols):
                col_vals = [grid[r][c] for r in range(n_rows)]
                if all(v == col_vals[0] for v in col_vals):
                    cols.append((c, col_vals[0]))
            common = set(cols) if common is None else common & set(cols)
        if not common:
            return []
        cand = []
        for sep_c, _ in common:
            def left_fn(g, sc=sep_c):
                return crop_vertical(g, sc, True)
            def right_fn(g, sc=sep_c):
                return crop_vertical(g, sc, False)
            cand.append((left_fn, f"vertical left of col {sep_c}"))
            cand.append((right_fn, f"vertical right of col {sep_c}"))
        return cand

    def horizontal_crop_candidates():
        common = None
        for ex in self.examples:
            grid = ex['input']
            n_rows, n_cols = len(grid), len(grid[0])
            rows = []
            for r in range(n_rows):
                row_vals = grid[r]
                if all(v == row_vals[0] for v in row_vals):
                    rows.append((r, row_vals[0]))
            common = set(rows) if common is None else common & set(rows)
        if not common:
            return []
        cand = []
        for sep_r, _ in common:
            def top_fn(g, sr=sep_r):
                return crop_horizontal(g, sr, True)
            def bottom_fn(g, sr=sep_r):
                return crop_horizontal(g, sr, False)
            cand.append((top_fn, f"horizontal top of row {sep_r}"))
            cand.append((bottom_fn, f"horizontal bottom of row {sep_r}"))
        return cand

    # Build the set of colours appearing in any example (including background)
    all_colours = set()
    for ex in self.examples:
        for row in ex['input']:
            all_colours.update(row)

    def colour_removal_candidates():
        return [(lambda g, col=col: remove_colour(g, col), f"remove colour {col}") for col in all_colours]

    def colour_replace_candidates():
        cand = []
        for src in all_colours:
            for dst in all_colours:
                if src != dst:
                    def fn(g, s=src, d=dst):
                        return replace_colour(g, s, d)
                    cand.append((fn, f"replace {src} with {dst}"))
        return cand

    def bbox_candidates():
        return [(lambda g, colour=col: extract_bbox(g, colour), f"extract bbox of colour {col}") for col in all_colours]

    hypothesis_families = [
        vertical_crop_candidates,
        horizontal_crop_candidates,
        colour_removal_candidates,
        colour_replace_candidates,
        bbox_candidates,
    ]

    for family_fn in hypothesis_families:
        for apply_fn, _ in family_fn():
            all_match = True
            for ex in self.examples:
                inp, out_expected = ex['input'], ex['output']
                out_candidate = apply_fn(inp)
                if out_candidate is None or out_candidate != out_expected:
                    all_match = False
                    break
            if all_match:
                test_out = apply_fn(self.test_input)
                if is_grid(test_out):
                    return test_out

    # ---------------------------------------------------------------------
    # 5️⃣ Rule‑guided code generation / repair pipeline (as in generation 9)
    # ---------------------------------------------------------------------
    # 5.1 Extract a concise natural‑language rule (deterministic low temperature)
    rule_instr = (
        "Examine the three example input‑output pairs and describe in a single sentence "
        "the transformation rule that maps any input grid to its output grid. "
        "Do not mention specific colours or coordinates; just state the general rule. "
        "Return only the description as plain text."
    )
    rule_agent = LLMAgentBase(
        output_fields=["thinking"],
        agent_name="RuleExtractor",
        role="Rule Extractor",
        temperature=0.1,
    )
    rule_text = rule_agent([taskInfo], rule_instr)[0].content

    # 5.2 Generate a handful of candidate programs guided by the rule
    N_code = 5
    candidates = []
    for i in range(N_code):
        code_prompt = (
            f"Rule: {rule_text}\n"
            "Based on the rule, write a Python function named `transform` that takes a "
            "list[list[int]] as input and returns the transformed grid. The function must "
            "work for the three example input‑output pairs provided in the task description."
        )
        code_agent = LLMAgentBase(
            output_fields=["thinking", "code"],
            agent_name=f"CodeGen_{i}",
            role="Code Generator",
            temperature=0.7,
        )
        _ , code_info = code_agent([taskInfo], code_prompt, iteration_idx=i)
        _ , correct_examples, _ = self.run_examples_and_get_feedback(code_info)
        candidates.append({"code_info": code_info, "correct_count": len(correct_examples)})

    # 5.3 Choose the best candidate (most solved examples) and use it if it solves at least one
    candidates.sort(key=lambda x: x["correct_count"], reverse=True)
    best_candidate = candidates[0] if candidates else None
    if best_candidate and best_candidate["correct_count"] > 0:
        answer = self.get_test_output_from_code(best_candidate["code_info"])
        if is_grid(answer):
            return answer
        # otherwise fall through to final fallback

    # ---------------------------------------------------------------------
    # 6️⃣ Final fallback: deterministic direct‑answer model
    # ---------------------------------------------------------------------
    final_instr = (
        "Please examine the three example input‑output pairs, infer the transformation rule, "
        "and then apply that rule to the test input given at the end. Return ONLY the resulting "
        "grid as a JSON list of lists of integers."
    )
    direct_agent = LLMAgentBase(
        output_fields=["answer"],
        agent_name="DirectAnswerFallback",
        role="ARC Solver",
        temperature=0.1,
    )
    answer_grid = direct_agent([taskInfo], final_instr)[0].content
    return answer_grid if is_grid(answer_grid) else []

def forward(self, taskInfo):
    """Solve an ARC task by extracting a structured rule, parsing it into a
    deterministic operation, and applying it. If parsing fails or the
    operation does not satisfy all examples, fall back to deterministic
    hypothesis families, then to a rule‑guided code‑generation/repair pipeline,
    and finally to a low‑temperature direct‑answer model.
    Returns the output grid as a list of list of ints.
    """

    # ---------------------------------------------------------------------
    # Imports & helper functions
    # ---------------------------------------------------------------------
    import re

    def is_grid(g):
        """Return True if *g* is a list of lists (grid)."""
        return isinstance(g, list) and all(isinstance(r, list) for r in g)

    def parse_params(param_str):
        """Parse a comma‑separated ``key=value`` string into a dict.
        Handles empty strings gracefully.
        """
        params = {}
        if not param_str:
            return params
        for pair in param_str.split(','):
            if '=' in pair:
                k, v = pair.split('=', 1)
                params[k.strip().lower()] = v.strip()
        return params

    # ---------------------------------------------------------------------
    # Guard – if no examples are provided, ask a low‑temperature model directly
    # ---------------------------------------------------------------------
    if not self.examples:
        fallback_instr = (
            "Please examine the three example input‑output pairs, infer the transformation rule, "
            "and then apply that rule to the test input given at the end. Return ONLY the resulting "
            "grid as a JSON list of lists of integers."
        )
        direct_agent = LLMAgentBase(
            output_fields=["answer"],
            agent_name="DirectAnswerFallback",
            role="ARC Solver",
            temperature=0.1,
        )
        return direct_agent([taskInfo], fallback_instr)[0].content

    # ---------------------------------------------------------------------
    # 1️⃣ Structured rule extraction (deterministic, low temperature)
    # ---------------------------------------------------------------------
    rule_instruction = (
        "Examine the three example input‑output pairs and describe the transformation "
        "using **exactly one line** that follows this template: \n"
        "`ACTION: <ACTION_NAME>; PARAMS: key1=value1, key2=value2, ...`\n"
        "Allowed ACTION_NAME values are: CROP_SIDE, REMOVE_COLOUR, REPLACE_COLOUR, "
        "BBOX_COLOUR, FLIP, TRANSPOSE. For CROP_SIDE you must provide ``colour`` and ``side``. "
        "For REMOVE_COLOUR provide ``colour``. For REPLACE_COLOUR provide ``src`` and ``dst``. "
        "For BBOX_COLOUR provide ``colour``. For FLIP provide ``axis`` (H or V). TRANSPOSE takes no parameters. "
        "Return ONLY the line, no extra text."
    )
    rule_agent = LLMAgentBase(
        output_fields=["thinking"],
        agent_name="StructuredRuleExtractor",
        role="Rule Extractor",
        temperature=0.1,
    )
    rule_info = rule_agent([taskInfo], rule_instruction)[0]
    rule_text = rule_info.content.strip()

    # ---------------------------------------------------------------------
    # 2️⃣ Parse the structured rule (robust to missing PARAMS)
    # ---------------------------------------------------------------------
    action = None
    params = {}
    # Regex with optional PARAMS part
    m = re.fullmatch(r"ACTION:\s*(\w+);(?:\s*PARAMS:\s*(.*))?", rule_text, re.IGNORECASE)
    if m:
        action = m.group(1).upper()
        params_part = m.group(2) or ""
        params = parse_params(params_part)
    # If parsing fails, ``action`` stays ``None`` and we will skip to fallback.

    # ---------------------------------------------------------------------
    # 3️⃣ Build deterministic operation from the parsed rule
    # ---------------------------------------------------------------------
    def build_operation(action, params):
        if action == "CROP_SIDE":
            try:
                colour = int(params.get('colour'))
                side = params.get('side', '').upper()
            except Exception:
                return None
            def op(grid):
                rows, cols = len(grid), len(grid[0])
                # Search for uniform column of the given colour
                for c in range(cols):
                    if all(grid[r][c] == colour for r in range(rows)):
                        if side == "LEFT":
                            return [row[:c] for row in grid]
                        if side == "RIGHT":
                            return [row[c+1:] for row in grid]
                # Search for uniform row of the given colour
                for r in range(rows):
                    if all(grid[r][c] == colour for c in range(cols)):
                        if side == "TOP":
                            return grid[:r]
                        if side == "BOTTOM":
                            return grid[r+1:]
                return None
            return op
        elif action == "REMOVE_COLOUR":
            try:
                colour = int(params.get('colour'))
            except Exception:
                return None
            return lambda g: [[0 if cell == colour else cell for cell in row] for row in g]
        elif action == "REPLACE_COLOUR":
            try:
                src = int(params.get('src'))
                dst = int(params.get('dst'))
            except Exception:
                return None
            return lambda g: [[dst if cell == src else cell for cell in row] for row in g]
        elif action == "BBOX_COLOUR":
            try:
                colour = int(params.get('colour'))
            except Exception:
                return None
            def op(grid):
                rows, cols = len(grid), len(grid[0])
                coords = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == colour]
                if not coords:
                    return None
                rs, cs = zip(*coords)
                r0, r1 = min(rs), max(rs) + 1
                c0, c1 = min(cs), max(cs) + 1
                return [grid[i][c0:c1] for i in range(r0, r1)]
            return op
        elif action == "FLIP":
            axis = params.get('axis', '').upper()
            if axis == 'H':
                return lambda g: g[::-1]
            if axis == 'V':
                return lambda g: [row[::-1] for row in g]
            return None
        elif action == "TRANSPOSE":
            return lambda g: [list(row) for row in zip(*g)]
        else:
            return None

    operation = None
    if action is not None:
        operation = build_operation(action, params)

    # ---------------------------------------------------------------------
    # 4️⃣ Verify operation on all examples
    # ---------------------------------------------------------------------
    if operation is not None:
        all_match = True
        for ex in self.examples:
            inp, out_expected = ex['input'], ex['output']
            out_candidate = operation(inp)
            if out_candidate is None or out_candidate != out_expected:
                all_match = False
                break
        if all_match:
            test_out = operation(self.test_input)
            if is_grid(test_out):
                return test_out
            # If the operation produced an invalid grid, fall through to fallback.

    # ---------------------------------------------------------------------
    # 5️⃣ Fallback 1 – deterministic hypothesis families (cleaned up)
    # ---------------------------------------------------------------------
    # Primitive helpers
    def crop_vertical(grid, sep_c, keep_left):
        return [row[:sep_c] if keep_left else row[sep_c+1:] for row in grid]
    def crop_horizontal(grid, sep_r, keep_top):
        return grid[:sep_r] if keep_top else grid[sep_r+1:]
    def remove_colour(grid, colour):
        return [[0 if cell == colour else cell for cell in row] for row in grid]
    def replace_colour(grid, src, dst):
        return [[dst if cell == src else cell for cell in row] for row in grid]
    def extract_bbox(grid, colour):
        rows = [i for i, row in enumerate(grid) if colour in row]
        cols = [j for j in range(len(grid[0])) if any(grid[i][j] == colour for i in range(len(grid)))]
        if not rows or not cols:
            return None
        r0, r1 = min(rows), max(rows)+1
        c0, c1 = min(cols), max(cols)+1
        return [grid[i][c0:c1] for i in range(r0, r1)]
    def flip_h(grid):
        return grid[::-1]
    def flip_v(grid):
        return [row[::-1] for row in grid]
    def transpose(grid):
        return [list(row) for row in zip(*grid)]

    # Families generating (apply_fn, description) tuples
    def vertical_crop_candidates():
        common = None
        for ex in self.examples:
            grid = ex['input']
            rows, cols = len(grid), len(grid[0])
            cols_info = []
            for c in range(cols):
                col_vals = [grid[r][c] for r in range(rows)]
                if all(v == col_vals[0] for v in col_vals):
                    cols_info.append((c, col_vals[0]))
            common = set(cols_info) if common is None else common & set(cols_info)
        if not common:
            return []
        cand = []
        for sep_c, _ in common:
            cand.append((lambda g, sc=sep_c: crop_vertical(g, sc, True), f"crop left of col {sep_c}"))
            cand.append((lambda g, sc=sep_c: crop_vertical(g, sc, False), f"crop right of col {sep_c}"))
        return cand

    def horizontal_crop_candidates():
        common = None
        for ex in self.examples:
            grid = ex['input']
            rows, cols = len(grid), len(grid[0])
            rows_info = []
            for r in range(rows):
                row_vals = grid[r]
                if all(v == row_vals[0] for v in row_vals):
                    rows_info.append((r, row_vals[0]))
            common = set(rows_info) if common is None else common & set(rows_info)
        if not common:
            return []
        cand = []
        for sep_r, _ in common:
            cand.append((lambda g, sr=sep_r: crop_horizontal(g, sr, True), f"crop top of row {sep_r}"))
            cand.append((lambda g, sr=sep_r: crop_horizontal(g, sr, False), f"crop bottom of row {sep_r}"))
        return cand

    def colour_removal_candidates():
        colours = set()
        for ex in self.examples:
            for row in ex['input']:
                colours.update(row)
        return [(lambda g, col=col: remove_colour(g, col), f"remove colour {col}") for col in colours]

    def colour_replace_candidates():
        colours = set()
        for ex in self.examples:
            for row in ex['input']:
                colours.update(row)
        cand = []
        for src in colours:
            for dst in colours:
                if src == dst:
                    continue
                cand.append((lambda g, s=src, d=dst: replace_colour(g, s, d), f"replace {src} with {dst}"))
        return cand

    def bbox_candidates():
        colours = set()
        for ex in self.examples:
            for row in ex['input']:
                colours.update(row)
        return [(lambda g, col=col: extract_bbox(g, col), f"bbox of colour {col}") for col in colours]

    def flip_candidates():
        return [(flip_h, "flip horizontal"), (flip_v, "flip vertical")]

    def transpose_candidates():
        return [(transpose, "transpose")]

    hypothesis_families = [
        vertical_crop_candidates,
        horizontal_crop_candidates,
        colour_removal_candidates,
        colour_replace_candidates,
        bbox_candidates,
        flip_candidates,
        transpose_candidates,
    ]

    for family_fn in hypothesis_families:
        for apply_fn, _ in family_fn():
            all_match = True
            for ex in self.examples:
                if apply_fn(ex['input']) != ex['output']:
                    all_match = False
                    break
            if all_match:
                test_out = apply_fn(self.test_input)
                if is_grid(test_out):
                    return test_out

    # ---------------------------------------------------------------------
    # 6️⃣ Fallback 2 – rule‑guided code generation / repair (as in Generation 9)
    # ---------------------------------------------------------------------
    rule_instr = (
        "Examine the three example input‑output pairs and describe in a single sentence "
        "the transformation rule that maps any input grid to its output grid. "
        "Do not mention specific colours or coordinates; just state the general rule. "
        "Return only the description as plain text."
    )
    rule_agent2 = LLMAgentBase(
        output_fields=["thinking"],
        agent_name="RuleExtractor",
        role="Rule Extractor",
        temperature=0.1,
    )
    rule_text2 = rule_agent2([taskInfo], rule_instr)[0].content

    N_code = 5
    code_candidates = []
    for i in range(N_code):
        code_prompt = (
            f"Rule: {rule_text2}\n"
            "Based on the rule, write a Python function named `transform` that takes a "
            "list[list[int]] as input and returns the transformed grid. The function must "
            "work for the three example input‑output pairs provided in the task description."
        )
        code_agent = LLMAgentBase(
            output_fields=["thinking", "code"],
            agent_name=f"CodeGen_{i}",
            role="Code Generator",
            temperature=0.7,
        )
        _ , code_info = code_agent([taskInfo], code_prompt, iteration_idx=i)
        _ , correct_examples, _ = self.run_examples_and_get_feedback(code_info)
        code_candidates.append({"code_info": code_info, "correct_count": len(correct_examples)})

    code_candidates.sort(key=lambda x: x["correct_count"], reverse=True)
    best_code = code_candidates[0] if code_candidates else None
    if best_code and best_code["correct_count"] > 0:
        answer = self.get_test_output_from_code(best_code["code_info"])
        if is_grid(answer):
            return answer
        # otherwise continue to final fallback

    # ---------------------------------------------------------------------
    # 7️⃣ Final fallback – low‑temperature direct answer model
    # ---------------------------------------------------------------------
    final_instr = (
        "Please examine the three example input‑output pairs, infer the transformation rule, "
        "and then apply that rule to the test input given at the end. Return ONLY the resulting "
        "grid as a JSON list of lists of integers."
    )
    final_agent = LLMAgentBase(
        output_fields=["answer"],
        agent_name="DirectAnswerFallback",
        role="ARC Solver",
        temperature=0.1,
    )
    answer_grid = final_agent([taskInfo], final_instr)[0].content
    # As a safety net, ensure we return a grid; otherwise return an empty list.
    return answer_grid if is_grid(answer_grid) else []

def forward(self, taskInfo):
    """Hierarchical ARC solver.
    1️⃣ Try a deterministic one‑line rule (crop, colour‑map, etc.).
    2️⃣ If that fails, run a *pruned* breadth‑first search over a DSL of primitives
       (depth ≤ 3).  Branches that do not match **all** training examples are
       discarded immediately, and duplicate programs (same effect on the first
       example) are not re‑expanded.
    3️⃣ If a program solving all examples is found, apply it to the test input.
    4️⃣ Otherwise fall back to a self‑consistency voting stage (several
       high‑temperature direct‑answer queries).
    5️⃣ Final low‑temperature direct answer as a safety net.
    Returns the output grid (list of list of ints)."""

    # ---------------------------------------------------------------------
    # Helper utilities
    # ---------------------------------------------------------------------
    def is_grid(g):
        return isinstance(g, list) and all(isinstance(r, list) for r in g)

    def apply_program(grid, prog):
        out = grid
        for fn in prog:
            out = fn(out)
            if out is None:
                return None
        return out

    # ---------------------------------------------------------------------
    # Guard: no examples → low‑temp direct answer
    # ---------------------------------------------------------------------
    if not self.examples:
        instr = (
            "Please examine the three example input–output pairs, infer the transformation rule, "
            "and then apply that rule to the test input given at the end. Return ONLY the resulting "
            "grid as a JSON list of lists of integers."
        )
        agent = LLMAgentBase(
            output_fields=["answer"],
            agent_name="DirectAnswerFallback",
            role="ARC Solver",
            temperature=0.1,
        )
        return agent([taskInfo], instr)[0].content

    # ---------------------------------------------------------------------
    # 1️⃣ Structured one‑line rule extraction (deterministic, low temperature)
    # ---------------------------------------------------------------------
    rule_instr = (
        "Examine the three example input–output pairs and describe the transformation using **exactly one line** that follows this template: \\n        `ACTION: <ACTION_NAME>; PARAMS: key1=value1, key2=value2, ...`\\n"
        "Allowed ACTION_NAME values are: CROP_SIDE, REMOVE_COLOUR, REPLACE_COLOUR, BBOX_COLOUR, FLIP, TRANSPOSE, GLOBAL_MAP.\\n"
        "For CROP_SIDE provide `colour` and `side` (LEFT, RIGHT, TOP, BOTTOM). For REMOVE_COLOUR provide `colour`. "
        "For REPLACE_COLOUR provide `src` and `dst`. For BBOX_COLOUR provide `colour`. For FLIP provide `axis` (H or V). GLOBAL_MAP needs no params. "
        "Return ONLY the line, no extra text."
    )
    rule_agent = LLMAgentBase(
        output_fields=["thinking"],
        agent_name="StructuredRuleExtractor",
        role="Rule Extractor",
        temperature=0.1,
    )
    rule_info = rule_agent([taskInfo], rule_instr)[0]
    rule_line = rule_info.content.strip()

    import re
    def parse_rule(line):
        m = re.fullmatch(r"ACTION:\s*(\w+);\s*PARAMS:\s*(.*)", line, re.IGNORECASE)
        if not m:
            m2 = re.fullmatch(r"ACTION:\s*(\w+)", line, re.IGNORECASE)
            if not m2:
                return None, {}
            return m2.group(1).upper(), {}
        action = m.group(1).upper()
        params_str = m.group(2).strip()
        params = {}
        if params_str:
            for pair in params_str.split(','):
                if '=' in pair:
                    k, v = pair.split('=', 1)
                    params[k.strip().lower()] = v.strip()
        return action, params

    action, params = parse_rule(rule_line)

    def build_operation(action, params):
        if action == "CROP_SIDE":
            try:
                colour = int(params.get('colour'))
                side = params.get('side', '').upper()
            except Exception:
                return None
            def op(grid):
                rows, cols = len(grid), len(grid[0])
                for c in range(cols):
                    if all(grid[r][c] == colour for r in range(rows)):
                        if side == "LEFT":
                            return [row[:c] for row in grid]
                        if side == "RIGHT":
                            return [row[c+1:] for row in grid]
                for r in range(rows):
                    if all(grid[r][c] == colour for c in range(cols)):
                        if side == "TOP":
                            return grid[:r]
                        if side == "BOTTOM":
                            return grid[r+1:]
                return None
            return op
        if action == "REMOVE_COLOUR":
            try:
                colour = int(params.get('colour'))
            except Exception:
                return None
            return lambda g: [[0 if cell == colour else cell for cell in row] for row in g]
        if action == "REPLACE_COLOUR":
            try:
                src = int(params.get('src'))
                dst = int(params.get('dst'))
            except Exception:
                return None
            return lambda g: [[dst if cell == src else cell for cell in row] for row in g]
        if action == "BBOX_COLOUR":
            try:
                colour = int(params.get('colour'))
            except Exception:
                return None
            def op(g):
                rows, cols = len(g), len(g[0])
                coords = [(r, c) for r in range(rows) for c in range(cols) if g[r][c] == colour]
                if not coords:
                    return None
                rs, cs = zip(*coords)
                r0, r1 = min(rs), max(rs) + 1
                c0, c1 = min(cs), max(cs) + 1
                return [g[i][c0:c1] for i in range(r0, r1)]
            return op
        if action == "FLIP":
            axis = params.get('axis', '').upper()
            if axis == 'H':
                return lambda g: g[::-1]
            if axis == 'V':
                return lambda g: [row[::-1] for row in g]
            return None
        if action == "TRANSPOSE":
            return lambda g: [list(r) for r in zip(*g)]
        if action == "GLOBAL_MAP":
            mapping = {}
            for ex in self.examples:
                inp, out = ex['input'], ex['output']
                if len(inp) != len(out) or len(inp[0]) != len(out[0]):
                    return None
                for r in range(len(inp)):
                    for c in range(len(inp[0])):
                        ic, oc = inp[r][c], out[r][c]
                        if ic in mapping:
                            if mapping[ic] != oc:
                                return None
                        else:
                            mapping[ic] = oc
            return lambda g: [[mapping.get(cell, cell) for cell in row] for row in g]
        return None

    deterministic_op = None
    if action is not None:
        deterministic_op = build_operation(action, params)
    if deterministic_op is not None:
        ok = True
        for ex in self.examples:
            if deterministic_op(ex['input']) != ex['output']:
                ok = False
                break
        if ok:
            test_out = deterministic_op(self.test_input)
            if is_grid(test_out):
                return test_out
        # otherwise continue to BFS

    # ---------------------------------------------------------------------
    # 2️⃣ Primitive set (including separator‑based crops and bounding‑box extracts)
    # ---------------------------------------------------------------------
    primitives = []  # (name, function)
    primitives.append(("identity", lambda g: g))
    # Geometric transforms
    primitives.append(("rotate90", lambda g: [list(r) for r in zip(*g[::-1])]))
    primitives.append(("rotate180", lambda g: [row[::-1] for row in g[::-1]]))
    # rotate270 as rotate90 three times for clarity
    primitives.append(("rotate270", lambda g: apply_program(apply_program(apply_program(g, [primitives[1][1]]), [primitives[1][1]]), [primitives[1][1]])))
    primitives.append(("flip_h", lambda g: g[::-1]))
    primitives.append(("flip_v", lambda g: [row[::-1] for row in g]))
    primitives.append(("transpose", lambda g: [list(r) for r in zip(*g)]))
    # Colours present in any example input
    all_colours = set()
    for ex in self.examples:
        for row in ex['input']:
            all_colours.update(row)
    for col in all_colours:
        primitives.append((f"remove_{col}", (lambda c: (lambda g: [[0 if cell == c else cell for cell in row] for row in g]))(col)))
    for src in all_colours:
        for dst in all_colours:
            if src == dst:
                continue
            primitives.append((f"replace_{src}_to_{dst}", (lambda s, d: (lambda g: [[d if cell == s else cell for cell in row] for row in g]))(src, dst)))
    # Global colour map (if consistent)
    def infer_global_map():
        mapping = {}
        for ex in self.examples:
            inp, out = ex['input'], ex['output']
            if len(inp) != len(out) or len(inp[0]) != len(out[0]):
                return None
            for r in range(len(inp)):
                for c in range(len(inp[0])):
                    ic, oc = inp[r][c], out[r][c]
                    if ic in mapping:
                        if mapping[ic] != oc:
                            return None
                    else:
                        mapping[ic] = oc
        return mapping
    global_map = infer_global_map()
    if global_map is not None:
        primitives.append(("global_map", (lambda m: (lambda g: [[m.get(cell, cell) for cell in row] for row in g]))(global_map)))
    # Uniform separator side‑crops
    def detect_uniform_separators():
        candidates = []  # (orientation, index, colour)
        # vertical
        common_cols = None
        for ex in self.examples:
            grid = ex['input']
            rows, cols = len(grid), len(grid[0])
            cols_info = []
            for c in range(cols):
                col_vals = [grid[r][c] for r in range(rows)]
                if all(v == col_vals[0] for v in col_vals):
                    cols_info.append((c, col_vals[0]))
            common_cols = set(cols_info) if common_cols is None else common_cols & set(cols_info)
        if common_cols:
            for idx, colour in common_cols:
                candidates.append(("vertical", idx, colour))
        # horizontal
        common_rows = None
        for ex in self.examples:
            grid = ex['input']
            rows, cols = len(grid), len(grid[0])
            rows_info = []
            for r in range(rows):
                row_vals = grid[r]
                if all(v == row_vals[0] for v in row_vals):
                    rows_info.append((r, row_vals[0]))
            common_rows = set(rows_info) if common_rows is None else common_rows & set(rows_info)
        if common_rows:
            for idx, colour in common_rows:
                candidates.append(("horizontal", idx, colour))
        return candidates
    separators = detect_uniform_separators()
    for orient, idx, _ in separators:
        if orient == "vertical":
            primitives.append((f"crop_left_of_{idx}", (lambda i: (lambda g: [row[:i] for row in g]))(idx)))
            primitives.append((f"crop_right_of_{idx}", (lambda i: (lambda g: [row[i+1:] for row in g]))(idx)))
        else:
            primitives.append((f"crop_top_of_{idx}", (lambda i: (lambda g: g[:i]))(idx)))
            primitives.append((f"crop_bottom_of_{idx}", (lambda i: (lambda g: g[i+1:]))(idx)))
    # Bounding‑box primitives for each colour
    colours_seen = set()
    for ex in self.examples:
        for row in ex['input']:
            colours_seen.update(row)
    for col in colours_seen:
        def make_bbox(colour):
            def bbox(g):
                rows = len(g)
                cols = len(g[0]) if rows else 0
                coords = [(r, c) for r in range(rows) for c in range(cols) if g[r][c] == colour]
                if not coords:
                    return None
                rs, cs = zip(*coords)
                r0, r1 = min(rs), max(rs) + 1
                c0, c1 = min(cs), max(cs) + 1
                return [g[i][c0:c1] for i in range(r0, r1)]
            return bbox
        primitives.append((f"bbox_of_{col}", make_bbox(col)))

    # ---------------------------------------------------------------------
    # 3️⃣ Pruned BFS (depth ≤ 3) with per‑depth node caps
    # ---------------------------------------------------------------------
    max_depth = 3
    node_cap = 5000  # maximum nodes per depth
    from collections import deque
    queue = deque()
    queue.append(([], []))  # (list of functions, list of names)
    seen_hashes = set()
    successful_program = None
    nodes_per_depth = {0: 1}
    while queue:
        prog_fns, prog_names = queue.popleft()
        depth = len(prog_fns)
        # Test current program (skip depth 0)
        if depth > 0:
            first_out = apply_program(self.examples[0]['input'], prog_fns)
            if first_out is None:
                continue
            prog_hash = tuple(tuple(row) for row in first_out)
            if prog_hash in seen_hashes:
                continue
            seen_hashes.add(prog_hash)
            # Verify on all examples
            all_ok = True
            for ex in self.examples:
                out = apply_program(ex['input'], prog_fns)
                if out is None or out != ex['output']:
                    all_ok = False
                    break
            if all_ok:
                successful_program = (prog_fns, prog_names)
                break
        # Expand if depth < max_depth and we haven't hit the node cap for next depth
        if depth < max_depth:
            next_depth = depth + 1
            if nodes_per_depth.get(next_depth, 0) >= node_cap:
                continue
            for name, fn in primitives:
                # simple pruning: avoid consecutive identities
                if name == "identity" and prog_names and prog_names[-1] == "identity":
                    continue
                new_fns = prog_fns + [fn]
                new_names = prog_names + [name]
                queue.append((new_fns, new_names))
                nodes_per_depth[next_depth] = nodes_per_depth.get(next_depth, 0) + 1

    if successful_program is not None:
        prog_fns, _ = successful_program
        result = apply_program(self.test_input, prog_fns)
        if is_grid(result):
            return result
        # fall through if malformed (unlikely)

    # ---------------------------------------------------------------------
    # 4️⃣ Self‑consistency voting (high temperature)
    # ---------------------------------------------------------------------
    def self_consistent_answer(samples=7):
        instr = (
            "Please examine the three example input–output pairs, infer the transformation rule, "
            "and then apply that rule to the test input given at the end. Return ONLY the resulting "
            "grid as a JSON list of lists of integers."
        )
        collected = []
        for i in range(samples):
            agent = LLMAgentBase(
                output_fields=["answer"],
                agent_name=f"SelfCons_{i}",
                role="ARC Solver",
                temperature=0.7,
            )
            ans = agent([taskInfo], instr)[0].content
            if is_grid(ans):
                collected.append(ans)
        if not collected:
            return None
        votes = {}
        for g in collected:
            key = tuple(tuple(row) for row in g)
            votes[key] = votes.get(key, 0) + 1
        best_key = max(votes.items(), key=lambda kv: kv[1])[0]
        return [list(row) for row in best_key]

    sc_grid = self_consistent_answer(samples=7)
    if sc_grid is not None:
        return sc_grid

    # ---------------------------------------------------------------------
    # 5️⃣ Final low‑temperature direct answer fallback
    # ---------------------------------------------------------------------
    final_instr = (
        "Please examine the three example input–output pairs, infer the transformation rule, "
        "and then apply that rule to the test input given at the end. Return ONLY the resulting "
        "grid as a JSON list of lists of integers."
    )
    final_agent = LLMAgentBase(
        output_fields=["answer"],
        agent_name="DirectAnswerFallback",
        role="ARC Solver",
        temperature=0.1,
    )
    final_grid = final_agent([taskInfo], final_instr)[0].content
    return final_grid if is_grid(final_grid) else final_grid

def forward(self, taskInfo):
    """Hybrid ARC solver:
    1️⃣ Deterministic quick detectors (colour map, uniform separator side‑crop, bbox).
    2️⃣ Neural sketch generation – LLM proposes short programs composed of primitives.
    3️⃣ Guided BFS up to depth 4, using a cached per‑depth primitive ranking from the LLM.
    4️⃣ Self‑consistency voting (high‑temperature direct‑answer queries).
    5️⃣ Low‑temperature direct‑answer fallback.
    Returns the output grid as a list of list of ints.
    """

    # ---------------------------------------------------------------------
    # Helper utilities
    # ---------------------------------------------------------------------
    def is_grid(g):
        return isinstance(g, list) and all(isinstance(r, list) for r in g)

    def apply_program(grid, prog):
        out = grid
        for fn in prog:
            out = fn(out)
            if out is None:
                return None
        return out

    # ---------------------------------------------------------------------
    # Guard: no examples → low‑temp direct answer
    # ---------------------------------------------------------------------
    if not self.examples:
        instr = (
            "Please examine the three example input‑output pairs, infer the transformation rule, "
            "and then apply that rule to the test input given at the end. Return ONLY the resulting "
            "grid as a JSON list of lists of integers."
        )
        agent = LLMAgentBase(
            output_fields=["answer"],
            agent_name="DirectAnswerFallback",
            role="ARC Solver",
            temperature=0.1,
        )
        return agent([taskInfo], instr)[0].content

    # ---------------------------------------------------------------------
    # 1️⃣ Deterministic quick detectors
    # ---------------------------------------------------------------------
    # ---- Colour‑mapping (many‑to‑one allowed) ----
    def infer_colour_map(examples):
        mapping = {}
        for ex in examples:
            inp, out = ex['input'], ex['output']
            if len(inp) != len(out) or len(inp[0]) != len(out[0]):
                return None
            for r in range(len(inp)):
                for c in range(len(inp[0])):
                    ic, oc = inp[r][c], out[r][c]
                    if ic in mapping:
                        if mapping[ic] != oc:
                            return None
                    else:
                        mapping[ic] = oc
        return mapping

    colour_map = infer_colour_map(self.examples)
    if colour_map is not None:
        def apply_map(grid):
            return [[colour_map.get(cell, cell) for cell in row] for row in grid]
        if all(apply_map(ex['input']) == ex['output'] for ex in self.examples):
            test_out = apply_map(self.test_input)
            if is_grid(test_out):
                return test_out

    # ---- Uniform separator detection ----
    def detect_uniform_lines(examples):
        candidates = []  # (orientation, index, colour)
        # vertical columns
        common_cols = None
        for ex in examples:
            grid = ex['input']
            rows, cols = len(grid), len(grid[0])
            cols_info = []
            for c in range(cols):
                col_vals = [grid[r][c] for r in range(rows)]
                if all(v == col_vals[0] for v in col_vals):
                    cols_info.append((c, col_vals[0]))
            common_cols = set(cols_info) if common_cols is None else common_cols & set(cols_info)
        if common_cols:
            for idx, colour in common_cols:
                candidates.append(("vertical", idx, colour))
        # horizontal rows
        common_rows = None
        for ex in examples:
            grid = ex['input']
            rows, cols = len(grid), len(grid[0])
            rows_info = []
            for r in range(rows):
                row_vals = grid[r]
                if all(v == row_vals[0] for v in row_vals):
                    rows_info.append((r, row_vals[0]))
            common_rows = set(rows_info) if common_rows is None else common_rows & set(rows_info)
        if common_rows:
            for idx, colour in common_rows:
                candidates.append(("horizontal", idx, colour))
        return candidates

    uniform_lines = detect_uniform_lines(self.examples)

    # ---- Side‑crop candidates (collect all that match examples) ----
    def side_crop_candidates():
        results = []
        for orientation, idx, _ in uniform_lines:
            sides = ["left", "right"] if orientation == "vertical" else ["top", "bottom"]
            for side in sides:
                ok = True
                for ex in self.examples:
                    inp, out = ex['input'], ex['output']
                    if orientation == "vertical":
                        cand = [row[:idx] if side == "left" else row[idx+1:] for row in inp]
                    else:
                        cand = inp[:idx] if side == "top" else inp[idx+1:]
                    if cand != out:
                        ok = False
                        break
                if ok:
                    test = self.test_input
                    if orientation == "vertical":
                        grid = [row[:idx] if side == "left" else row[idx+1:] for row in test]
                    else:
                        grid = test[:idx] if side == "top" else test[idx+1:]
                    if is_grid(grid):
                        results.append((grid, 'deterministic'))
        return results

    deterministic_grids = side_crop_candidates()

    # ---- Bounding‑box around cells different from separator colour ----
    def bbox_candidates():
        results = []
        for orientation, sep_idx, sep_colour in uniform_lines:
            boxes = []
            side_consistency = None
            for ex in self.examples:
                inp = ex['input']
                rows, cols = len(inp), len(inp[0])
                coords = [(r, c) for r in range(rows) for c in range(cols) if inp[r][c] != sep_colour]
                if not coords:
                    break
                rs, cs = zip(*coords)
                r0, r1 = min(rs), max(rs) + 1
                c0, c1 = min(cs), max(cs) + 1
                h, w = r1 - r0, c1 - c0
                boxes.append((r0, c0, h, w))
                # side detection
                if orientation == "vertical":
                    cur_side = "left" if c0 + w == sep_idx else "right" if c0 == sep_idx + 1 else None
                else:
                    cur_side = "top" if r0 + h == sep_idx else "bottom" if r0 == sep_idx + 1 else None
                if cur_side is None:
                    break
                if side_consistency is None:
                    side_consistency = cur_side
                elif side_consistency != cur_side:
                    break
            else:  # no break
                first_h, first_w = boxes[0][2], boxes[0][3]
                if all(b[2] == first_h and b[3] == first_w for b in boxes):
                    r0, c0 = boxes[0][0], boxes[0][1]
                    test = self.test_input
                    grid = [test[r0 + i][c0:c0 + first_w] for i in range(first_h)]
                    if is_grid(grid):
                        results.append((grid, 'deterministic'))
        return results

    deterministic_grids.extend(bbox_candidates())

    # If any deterministic grid was produced, return the most common one
    if deterministic_grids:
        vote = {}
        for grid, _ in deterministic_grids:
            key = tuple(tuple(row) for row in grid)
            vote[key] = vote.get(key, 0) + 1
        best_key = max(vote.items(), key=lambda kv: kv[1])[0]
        return [list(row) for row in best_key]

    # ---------------------------------------------------------------------
    # 2️⃣ Neural sketch generation
    # ---------------------------------------------------------------------
    # Build primitive catalogue (name → function)
    primitives = {}
    # geometric primitives
    def rotate90(g):
        return [list(r) for r in zip(*g[::-1])]
    def rotate180(g):
        return [row[::-1] for row in g[::-1]]
    def rotate270(g):
        return rotate90(rotate90(rotate90(g)))
    primitives["identity"] = lambda g: g
    primitives["rotate90"] = rotate90
    primitives["rotate180"] = rotate180
    primitives["rotate270"] = rotate270
    primitives["flip_h"] = lambda g: g[::-1]
    primitives["flip_v"] = lambda g: [row[::-1] for row in g]
    primitives["transpose"] = lambda g: [list(r) for r in zip(*g)]
    # colour‑based primitives
    all_colours = set()
    for ex in self.examples:
        for row in ex['input']:
            all_colours.update(row)
    for col in all_colours:
        primitives[f"remove_{col}"] = (lambda c: (lambda g: [[0 if cell == c else cell for cell in row] for row in g]))(col)
    for src in all_colours:
        for dst in all_colours:
            if src == dst:
                continue
            primitives[f"replace_{src}_to_{dst}"] = (lambda s, d: (lambda g: [[d if cell == s else cell for cell in row] for row in g]))(src, dst)
    # global colour map (if consistent)
    if colour_map is not None:
        primitives["global_map"] = (lambda m: (lambda g: [[m.get(cell, cell) for cell in row] for row in g]))(colour_map)
    # separator side‑crops
    for orientation, idx, _ in uniform_lines:
        if orientation == "vertical":
            primitives[f"crop_left_of_{idx}"] = (lambda i: (lambda g: [row[:i] for row in g]))(idx)
            primitives[f"crop_right_of_{idx}"] = (lambda i: (lambda g: [row[i+1:] for row in g]))(idx)
        else:
            primitives[f"crop_top_of_{idx}"] = (lambda i: (lambda g: g[:i]))(idx)
            primitives[f"crop_bottom_of_{idx}"] = (lambda i: (lambda g: g[i+1:]))(idx)
    # bbox primitives for each colour
    for col in all_colours:
        def make_bbox(colour):
            def bbox(g):
                rows = len(g)
                cols = len(g[0]) if rows else 0
                coords = [(r, c) for r in range(rows) for c in range(cols) if g[r][c] == colour]
                if not coords:
                    return None
                rs, cs = zip(*coords)
                r0, r1 = min(rs), max(rs) + 1
                c0, c1 = min(cs), max(cs) + 1
                return [g[i][c0:c1] for i in range(r0, r1)]
            return bbox
        primitives[f"bbox_of_{col}"] = make_bbox(col)

    # Prompt LLM for sketches
    primitive_list_str = ", ".join(sorted(primitives.keys()))
    sketch_instruction = (
        "Given the three example input‑output pairs, propose up to five short programs that could perform the transformation. "
        "Each program must be a sequence of primitive names from the list below, separated by '->' with no spaces. "
        f"Available primitives: {primitive_list_str}. "
        "Return the programs as plain text, one per line."
    )
    sketch_agent = LLMAgentBase(
        output_fields=["thinking", "code"],
        agent_name="SketchGenerator",
        role="Program Sketch Creator",
        temperature=0.1,
    )
    _ , sketch_info = sketch_agent([taskInfo], sketch_instruction)
    sketch_text = sketch_info.content.strip()

    import re
    candidate_programs = []
    for line in sketch_text.splitlines():
        m = re.search(r"([\w_]+(?:->[\w_]+)+)", line)
        if not m:
            continue
        prog_str = m.group(1)
        names = prog_str.split('->')
        if all(name in primitives for name in names):
            fn_list = [primitives[name] for name in names]
            candidate_programs.append((prog_str, fn_list))

    # Evaluate each sketch
    for prog_str, fn_list in candidate_programs:
        all_ok = True
        for ex in self.examples:
            out = apply_program(ex['input'], fn_list)
            if out is None or out != ex['output']:
                all_ok = False
                break
        if all_ok:
            test_out = apply_program(self.test_input, fn_list)
            if is_grid(test_out):
                return test_out

    # ---------------------------------------------------------------------
    # 3️⃣ Guided BFS (depth ≤ 4) with cached per‑depth primitive ranking
    # ---------------------------------------------------------------------
    max_depth = 4
    node_cap_per_depth = 2000
    from collections import deque
    queue = deque()
    queue.append(([], []))  # (list of functions, list of names)
    seen_hashes = set()
    successful = None
    nodes_at_depth = {0: 1}
    ranking_cache = {}

    def get_primitive_ranking(depth):
        """Return a list of primitive names ordered by LLM preference for the given depth.
        The ranking is cached per depth to avoid many LLM calls.
        """
        if depth in ranking_cache:
            return ranking_cache[depth]
        ranking_instr = (
            "Given the three example input‑output pairs and the list of available primitives, rank the primitives "
            "in order of how useful they are likely to be for solving the task. Return the names as a comma‑separated list."
        )
        rank_agent = LLMAgentBase(
            output_fields=["thinking", "code"],
            agent_name="PrimitiveRanker",
            role="Ranker",
            temperature=0.6,
        )
        _ , rank_info = rank_agent([taskInfo], ranking_instr)
        ordered = [name.strip() for name in rank_info.content.split(',') if name.strip() in primitives]
        if not ordered:
            ordered = list(primitives.keys())
        ranking_cache[depth] = ordered
        return ordered

    while queue:
        prog_fns, prog_names = queue.popleft()
        depth = len(prog_fns)
        # Test current program (skip empty)
        if depth > 0:
            first_out = apply_program(self.examples[0]['input'], prog_fns)
            if first_out is None:
                continue
            prog_hash = tuple(tuple(row) for row in first_out)
            if prog_hash in seen_hashes:
                continue
            seen_hashes.add(prog_hash)
            # Verify on all examples
            all_ok = True
            for ex in self.examples:
                out = apply_program(ex['input'], prog_fns)
                if out is None or out != ex['output']:
                    all_ok = False
                    break
            if all_ok:
                successful = (prog_fns, prog_names)
                break
        # Expand if depth < max_depth and node cap not exceeded
        if depth < max_depth:
            next_depth = depth + 1
            if nodes_at_depth.get(next_depth, 0) >= node_cap_per_depth:
                continue
            ordered_names = get_primitive_ranking(next_depth)
            for name in ordered_names:
                fn = primitives[name]
                if name == "identity" and prog_names and prog_names[-1] == "identity":
                    continue
                new_fns = prog_fns + [fn]
                new_names = prog_names + [name]
                queue.append((new_fns, new_names))
                nodes_at_depth[next_depth] = nodes_at_depth.get(next_depth, 0) + 1

    if successful is not None:
        prog_fns, _ = successful
        result = apply_program(self.test_input, prog_fns)
        if is_grid(result):
            return result

    # ---------------------------------------------------------------------
    # 4️⃣ Self‑consistency voting (high temperature direct answer)
    # ---------------------------------------------------------------------
    def self_consistency_answer(samples=7):
        instr = (
            "Please examine the three example input‑output pairs, infer the transformation rule, "
            "and then apply that rule to the test input given at the end. Return ONLY the resulting "
            "grid as a JSON list of lists of integers."
        )
        collected = []
        for i in range(samples):
            agent = LLMAgentBase(
                output_fields=["answer"],
                agent_name=f"SelfCons_{i}",
                role="ARC Solver",
                temperature=0.7,
            )
            ans = agent([taskInfo], instr)[0].content
            if is_grid(ans):
                collected.append(ans)
        if not collected:
            return None
        votes = {}
        for g in collected:
            key = tuple(tuple(row) for row in g)
            votes[key] = votes.get(key, 0) + 1
        best_key = max(votes.items(), key=lambda kv: kv[1])[0]
        return [list(row) for row in best_key]

    sc_grid = self_consistency_answer(samples=7)
    if sc_grid is not None:
        return sc_grid

    # ---------------------------------------------------------------------
    # 5️⃣ Final low‑temperature direct answer fallback
    # ---------------------------------------------------------------------
    final_instr = (
        "Please examine the three example input‑output pairs, infer the transformation rule, "
        "and then apply that rule to the test input given at the end. Return ONLY the resulting "
        "grid as a JSON list of lists of integers."
    )
    final_agent = LLMAgentBase(
        output_fields=["answer"],
        agent_name="DirectAnswerFallback",
        role="ARC Solver",
        temperature=0.1,
    )
    final_grid = final_agent([taskInfo], final_instr)[0].content
    return final_grid if is_grid(final_grid) else final_grid

