    def rotate90(g):
        return [list(r) for r in zip(*g[::-1])]
    def rotate180(g):
        return [row[::-1] for row in g[::-1]]
    def rotate270(g):
        # compose rotate90 three times
        return rotate90(rotate90(rotate90(g)))
    primitives["identity"] = lambda g: g
    primitives["rotate90"] = rotate90
    primitives["rotate180"] = rotate180
    primitives["rotate270"] = rotate270
    primitives["flip_h"] = lambda g: g[::-1]
    primitives["flip_v"] = lambda g: [row[::-1] for row in g]
    primitives["transpose"] = lambda g: [list(r) for r in zip(*g)]
    # colour primitives
    all_colours = set()
    for ex in self.examples:
        for row in ex['input']:
            all_colours.update(row)
    for col in all_colours:
        primitives[f"remove_{col}"] = (lambda c: (lambda g: [[0 if cell == c else cell for cell in row] for row in g]))(col)
    for src in all_colours:
        for dst in all_colours:
            if src == dst:
                continue
            primitives[f"replace_{src}_to_{dst}"] = (lambda s, d: (lambda g: [[d if cell == s else cell for cell in row] for row in g]))(src, dst)
    if colour_map is not None:
        primitives["global_map"] = (lambda m: (lambda g: [[m.get(cell, cell) for cell in row] for row in g]))(colour_map)
    # separator side‑crops
    for orientation, idx, _ in uniform_lines:
        if orientation == "vertical":
            primitives[f"crop_left_of_{idx}"] = (lambda i: (lambda g: [row[:i] for row in g]))(idx)
            primitives[f"crop_right_of_{idx}"] = (lambda i: (lambda g: [row[i+1:] for row in g]))(idx)
        else:
            primitives[f"crop_top_of_{idx}"] = (lambda i: (lambda g: g[:i]))(idx)
            primitives[f"crop_bottom_of_{idx}"] = (lambda i: (lambda g: g[i+1:]))(idx)
    # bbox primitives
    for col in all_colours:
        def make_bbox(colour):
            def bbox(g):
                rows = len(g)
                cols = len(g[0]) if rows else 0
                coords = [(r, c) for r in range(rows) for c in range(cols) if g[r][c] == colour]
                if not coords:
                    return None
                rs, cs = zip(*coords)
                r0, r1 = min(rs), max(rs) + 1
                c0, c1 = min(cs), max(cs) + 1
                return [g[i][c0:c1] for i in range(r0, r1)]
            return bbox
        primitives[f"bbox_of_{col}"] = make_bbox(col)

    max_depth = 4
    node_cap_per_depth = 3000
    from collections import deque
    queue = deque()
    queue.append(([], []))  # (list of functions, list of names)
    seen_hashes = set()
    successful = None
    nodes_at_depth = {0: 1}
    ranking_cache = {}

    def get_primitive_order(depth):
        """Return an LLM‑ranked ordering of primitive names for *depth*.
        The result is cached per depth.
        """
        if depth in ranking_cache:
            return ranking_cache[depth]
        rank_instr = (
            "Given the three example input‑output pairs and the list of available primitives, rank the primitives "
            "by how useful they are likely to be for solving the task. Return the names as a comma‑separated list."
        )
        rank_agent = LLMAgentBase(
            output_fields=["thinking"],
            agent_name="PrimitiveRanker",
            role="Ranker",
            temperature=0.6,
        )
        rank_output = rank_agent([taskInfo], rank_instr)
        rank_info = rank_output[0]
        ordered = [n.strip() for n in rank_info.content.split(',') if n.strip() in primitives]
        if not ordered:
            ordered = list(primitives.keys())
        ranking_cache[depth] = ordered
        return ordered

    while queue:
        prog_fns, prog_names = queue.popleft()
        depth = len(prog_fns)
        if depth > 0:
            first_out = apply_program(self.examples[0]['input'], prog_fns)
            if first_out is None:
                continue
            prog_hash = tuple(tuple(row) for row in first_out)
            if prog_hash in seen_hashes:
                continue
            seen_hashes.add(prog_hash)
            all_ok = True
            for ex in self.examples:
                out = apply_program(ex['input'], prog_fns)
                if out is None or out != ex['output']:
                    all_ok = False
                    break
            if all_ok:
                successful = (prog_fns, prog_names)
                break
        if depth < max_depth:
            next_depth = depth + 1
            if nodes_at_depth.get(next_depth, 0) >= node_cap_per_depth:
                continue
            ordered_names = get_primitive_order(next_depth)
            for name in ordered_names:
                fn = primitives[name]
                if name == "identity" and prog_names and prog_names[-1] == "identity":
                    continue
                queue.append((prog_fns + [fn], prog_names + [name]))
                nodes_at_depth[next_depth] = nodes_at_depth.get(next_depth, 0) + 1

    if successful is not None:
        prog_fns, _ = successful
        result = apply_program(self.test_input, prog_fns)
        if is_grid(result):
            return result

    # ---------------------------------------------------------------------
    # 3️⃣ Iterative code‑repair (rule extraction → generation → patch)
    # ---------------------------------------------------------------------
    rule_instr = (
        "Examine the three example input‑output pairs and describe the transformation rule in a single sentence. "
        "Do not mention specific colours or coordinates; just state the general rule. Return only the description as plain text."
    )
    rule_agent = LLMAgentBase(
        output_fields=["thinking"],
        agent_name="RuleExtractor",
        role="Rule Extractor",
        temperature=0.1,
    )
    rule_text = rule_agent([taskInfo], rule_instr)[0].content

    max_iters = 5
    best_code = None
    best_correct = -1
    cur_code = None
    prev_code_str = None
    for it in range(max_iters):
        if cur_code is None:
            prompt = (
                f"Rule: {rule_text}\n"
                "Write a Python function named `transform` that takes a list[list[int]] as input and returns the transformed grid. "
                "The function must work for the three example input‑output pairs provided in the task description."
            )
        else:
            feedback_info, _, _ = self.run_examples_and_get_feedback(cur_code)
            feedback = feedback_info.content
            prompt = (
                f"Rule: {rule_text}\n"
                f"Previous code:\n{cur_code.content}\n"
                f"Feedback (list of failing examples):\n{feedback}\n"
                "Modify the `transform` function to fix the reported failures while keeping the rest of the logic unchanged."
            )
        code_agent = LLMAgentBase(
            output_fields=["thinking", "code"],
            agent_name=f"RepairIter_{it}",
            role="Code Generator",
            temperature=0.7,
        )
        _ , code_info = code_agent([taskInfo], prompt, iteration_idx=it)
        _, correct_examples, _ = self.run_examples_and_get_feedback(code_info)
        corr_cnt = len(correct_examples)
        if corr_cnt > best_correct:
            best_correct = corr_cnt
            best_code = code_info
        if best_correct == len(self.examples):
            break
        cur_str = code_info.content
        if prev_code_str is not None and cur_str == prev_code_str:
            break
        prev_code_str = cur_str
        cur_code = code_info

    if best_code is not None and best_correct > 0:
        answer = self.get_test_output_from_code(best_code)
        if is_grid(answer):
            return answer
        # otherwise continue to self‑consistency

    # ---------------------------------------------------------------------
    # 4️⃣ Self‑consistency voting (high‑temperature direct answers)
    # ---------------------------------------------------------------------
    def self_consistency(samples=7):
        instr = (
            "Please examine the three example input‑output pairs, infer the transformation rule, "
            "and then apply that rule to the test input given at the end. Return ONLY the resulting "
            "grid as a JSON list of lists of integers."
        )
        collected = []
        for i in range(samples):
            agent = LLMAgentBase(
                output_fields=["answer"],
                agent_name=f"SelfCons_{i}",
                role="ARC Solver",
                temperature=0.7,
            )
            ans = agent([taskInfo], instr)[0].content
            if is_grid(ans):
                collected.append(ans)
        if not collected:
            return None
        votes = {}
        for g in collected:
            key = tuple(tuple(row) for row in g)
            votes[key] = votes.get(key, 0) + 1
        best_key = max(votes.items(), key=lambda kv: kv[1])[0]
        return [list(row) for row in best_key]

    sc_grid = self_consistency(samples=7)
    if sc_grid is not None:
        return sc_grid

    # ---------------------------------------------------------------------
    # 5️⃣ Final low‑temperature direct answer fallback
    # ---------------------------------------------------------------------
    final_instr = (
        "Please examine the three example input‑output pairs, infer the transformation rule, "
        "and then apply that rule to the test input given at the end. Return ONLY the resulting "
        "grid as a JSON list of lists of integers."
    )
    final_agent = LLMAgentBase(
        output_fields=["answer"],
        agent_name="DirectAnswerFallback",
        role="ARC Solver",
        temperature=0.1,
    )
    final_grid = final_agent([taskInfo], final_instr)[0].content
    return final_grid if is_grid(final_grid) else final_grid

def forward(self, taskInfo):
    """Hybrid ARC solver that first tries to extract an ordered list of high‑level actions
    (crop, recolor, flip, etc.) from the examples via an LLM. If the resulting program
    solves all training examples, it is applied to the test input. Otherwise we fall back
    to a high‑temperature self‑consistency voting of direct‑answer agents and finally a
    low‑temperature direct‑answer fallback.
    Returns the output grid as a list of list of ints.
    """

    # ---------------------------------------------------------------------
    # Helper utilities
    # ---------------------------------------------------------------------
    def is_grid(g):
        """Return True if *g* is a list of lists (grid)."""
        return isinstance(g, list) and all(isinstance(r, list) for r in g)

    def apply_program(grid, prog):
        """Apply a sequence of primitive callables to *grid*.
        Returns ``None`` if any primitive fails.
        """
        out = grid
        for fn in prog:
            out = fn(out)
            if out is None:
                return None
        return out

    # ---------------------------------------------------------------------
    # Guard: no examples → low‑temperature direct answer
    # ---------------------------------------------------------------------
    if not self.examples:
        instr = (
            "Please examine the three example input‑output pairs, infer the transformation rule, "
            "and then apply that rule to the test input given at the end. Return ONLY the resulting "
            "grid as a JSON list of lists of integers."
        )
        agent = LLMAgentBase(
            output_fields=["answer"],
            agent_name="DirectAnswerFallback",
            role="ARC Solver",
            temperature=0.1,
        )
        return agent([taskInfo], instr)[0].content

    # ---------------------------------------------------------------------
    # 1️⃣ Primitive factories (action → callable)
    # ---------------------------------------------------------------------
    def crop_left(colour):
        def fn(grid):
            rows, cols = len(grid), len(grid[0])
            for c in range(cols):
                if all(grid[r][c] == colour for r in range(rows)):
                    return [row[:c] for row in grid]
            return None
        return fn

    def crop_right(colour):
        def fn(grid):
            rows, cols = len(grid), len(grid[0])
            for c in range(cols):
                if all(grid[r][c] == colour for r in range(rows)):
                    return [row[c+1:] for row in grid]
            return None
        return fn

    def crop_top(colour):
        def fn(grid):
            rows, cols = len(grid), len(grid[0])
            for r in range(rows):
                if all(grid[r][c] == colour for c in range(cols)):
                    return grid[:r]
            return None
        return fn

    def crop_bottom(colour):
        def fn(grid):
            rows, cols = len(grid), len(grid[0])
            for r in range(rows):
                if all(grid[r][c] == colour for c in range(cols)):
                    return grid[r+1:]
            return None
        return fn

    def remove_colour(colour):
        return lambda g: [[0 if cell == colour else cell for cell in row] for row in g]

    def replace_colour(src, dst):
        return lambda g: [[dst if cell == src else cell for cell in row] for row in g]

    def bbox_colour(colour):
        def fn(g):
            rows, cols = len(g), len(g[0])
            coords = [(r, c) for r in range(rows) for c in range(cols) if g[r][c] == colour]
            if not coords:
                return None
            rs, cs = zip(*coords)
            r0, r1 = min(rs), max(rs) + 1
            c0, c1 = min(cs), max(cs) + 1
            return [g[i][c0:c1] for i in range(r0, r1)]
        return fn

    def flip_h():
        return lambda g: g[::-1]

    def flip_v():
        return lambda g: [row[::-1] for row in g]

    def transpose():
        return lambda g: [list(r) for r in zip(*g)]

    # Global colour map (computed once if possible)
    def infer_global_map():
        """Infer a many‑to‑one colour mapping that works for all examples.
        Returns ``None`` if the mapping is inconsistent.
        """
        mapping = {}
        for ex in self.examples:
            inp, out = ex['input'], ex['output']
            if len(inp) != len(out) or len(inp[0]) != len(out[0]):
                return None
            for r in range(len(inp)):
                for c in range(len(inp[0])):
                    ic, oc = inp[r][c], out[r][c]
                    if ic in mapping:
                        if mapping[ic] != oc:
                            return None
                    else:
                        mapping[ic] = oc
        return mapping

    GLOBAL_MAP_DICT = infer_global_map()

    def global_map():
        if GLOBAL_MAP_DICT is None:
            return None
        return lambda g: [[GLOBAL_MAP_DICT.get(cell, cell) for cell in row] for row in g]

    # Mapping from action name to a factory that builds the callable
    ACTION_FACTORIES = {
        "CROP_LEFT": lambda p: crop_left(int(p["colour"])) if "colour" in p else None,
        "CROP_RIGHT": lambda p: crop_right(int(p["colour"])) if "colour" in p else None,
        "CROP_TOP": lambda p: crop_top(int(p["colour"])) if "colour" in p else None,
        "CROP_BOTTOM": lambda p: crop_bottom(int(p["colour"])) if "colour" in p else None,
        "REMOVE_COLOUR": lambda p: remove_colour(int(p["colour"])) if "colour" in p else None,
        "REPLACE_COLOUR": lambda p: replace_colour(int(p["src"]), int(p["dst"])) if "src" in p and "dst" in p else None,
        "BBOX_COLOUR": lambda p: bbox_colour(int(p["colour"])) if "colour" in p else None,
        "FLIP_H": lambda p: flip_h(),
        "FLIP_V": lambda p: flip_v(),
        "TRANSPOSE": lambda p: transpose(),
        "GLOBAL_MAP": lambda p: global_map()
    }

    # ---------------------------------------------------------------------
    # 2️⃣ Ask LLM for ordered action list
    # ---------------------------------------------------------------------
    action_prompt = (
        "Given the three example input‑output pairs, describe the transformation as an ordered list of actions. "
        "Each line must contain one action in the exact form: ACTION_NAME param1=value1 param2=value2 ... "
        "If an action takes no parameters, just write the action name. "
        "Allowed ACTION_NAME values are: CROP_LEFT, CROP_RIGHT, CROP_TOP, CROP_BOTTOM, "
        "REMOVE_COLOUR, REPLACE_COLOUR, BBOX_COLOUR, FLIP_H, FLIP_V, TRANSPOSE, GLOBAL_MAP. "
        "All parameter values are integers. Return ONLY the list of actions, one per line, no extra text."
    )
    extractor = LLMAgentBase(
        output_fields=["thinking"],
        agent_name="ActionExtractor",
        role="Rule Extractor",
        temperature=0.1,
    )
    action_info = extractor([taskInfo], action_prompt)[0]
    action_text = action_info.content.strip()

    # ---------------------------------------------------------------------
    # 3️⃣ Parse actions into callables
    # ---------------------------------------------------------------------
    program_fns = []
    program_names = []
    for line in action_text.splitlines():
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        action_name = parts[0].upper()
        param_dict = {}
        for token in parts[1:]:
            if "=" in token:
                k, v = token.split("=", 1)
                param_dict[k.lower()] = v
        if action_name not in ACTION_FACTORIES:
            continue
        fn = ACTION_FACTORIES[action_name](param_dict)
        if fn is None:
            continue
        program_fns.append(fn)
        program_names.append(action_name)

    # ---------------------------------------------------------------------
    # 4️⃣ Validate the constructed program against all examples
    # ---------------------------------------------------------------------
    if program_fns:
        all_match = True
        for ex in self.examples:
            out = apply_program(ex['input'], program_fns)
            if out is None or out != ex['output']:
                all_match = False
                break
        if all_match:
            test_out = apply_program(self.test_input, program_fns)
            if is_grid(test_out):
                return test_out
            # fall through if malformed (unlikely)

    # ---------------------------------------------------------------------
    # 5️⃣ Fallback: high‑temperature self‑consistency voting of direct answers
    # ---------------------------------------------------------------------
    def self_consistency(samples=9):
        instr = (
            "Please examine the three example input‑output pairs, infer the transformation rule, "
            "and then apply that rule to the test input given at the end. Return ONLY the resulting "
            "grid as a JSON list of lists of integers."
        )
        collected = []
        for i in range(samples):
            agent = LLMAgentBase(
                output_fields=["answer"],
                agent_name=f"SelfCons_{i}",
                role="ARC Solver",
                temperature=0.7,
            )
            ans = agent([taskInfo], instr)[0].content
            if is_grid(ans):
                collected.append(ans)
        if not collected:
            return None
        votes = {}
        for g in collected:
            key = tuple(tuple(row) for row in g)
            votes[key] = votes.get(key, 0) + 1
        best_key = max(votes.items(), key=lambda kv: kv[1])[0]
        return [list(row) for row in best_key]

    sc_grid = self_consistency(samples=9)
    if sc_grid is not None:
        return sc_grid

    # ---------------------------------------------------------------------
    # 6️⃣ Final fallback: low‑temperature direct answer
    # ---------------------------------------------------------------------
    final_instr = (
        "Please examine the three example input‑output pairs, infer the transformation rule, "
        "and then apply that rule to the test input given at the end. Return ONLY the resulting "
        "grid as a JSON list of lists of integers."
    )
    final_agent = LLMAgentBase(
        output_fields=["answer"],
        agent_name="DirectAnswerFallback",
        role="ARC Solver",
        temperature=0.1,
    )
    final_grid = final_agent([taskInfo], final_instr)[0].content
    return final_grid if is_grid(final_grid) else final_grid
